package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sync"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// CounterNode represents a node in the cluster with a grow-only counter
type CounterNode struct {
	ID         string
	NodeIDs    []string
	node       *maelstrom.Node
	seqKV      *maelstrom.SeqKV
	wg         sync.WaitGroup
}

// addRequest represents an add request from a client
type addRequest struct {
	MsgID   int        `json:"msg_id"`
	Delta   int64      `json:"delta"`
	TTL     time.Duration
}

// addOKResponse represents the response to an add request
type addOKResponse struct {
	MsgID         int    `json:"msg_id"`
	InReplyTo     int    `json:"in_reply_to"`
	AckCount      int64  `json:"ack_count,omitempty"`
}

// readRequest represents a read request from a client
type readRequest struct {
	MsgID int `json:"msg_id"`
}

// readOKResponse represents the response to a read request
type readOKResponse struct {
	MsgID         int    `json:"msg_id"`
	InReplyTo     int    `json:"in_reply_to"`
	Value         int64  `json:"value"`
	TTL           time.Duration
}

// addResp is the message type for add responses
const addRespType = "add_ok"

// readResp is the message type for read responses  
const readRespType = "read_ok"

func main() {
	// Initialize the node
	node, err := maelstrom.NewNode(os.Stdin, os.Stdout)
	if err != nil {
		log.Fatalf("Failed to create node: %v", err)
	}
	defer node.Close()

	// Wait for init message to get node IDs
	initMsg := &maelstrom.Init{}
	err = node.Handle(initMsg)
	if err != nil {
		log.Fatalf("Failed to handle init: %v", err)
	}

	// Extract node info from init response
	// The init response will contain node ID and other nodes
	nodeID := ""
	if maelstrom.IsReply(node.Get()) {
		resp := node.Get().(*maelstrom.Reply)
		for _, msg := range resp.Message {
			switch msg.Type {
			case "init":
				body, _ := json.Marshal(msg.Body)
				log.Printf("Init body: %s", string(body))
				var initMsg struct {
					NodeID string `json:"node_id,omitempty"`
					Nodes  []string `json:"nodes,omitempty"`
				}
				json.Unmarshal(body, &initMsg)
				nodeID = initMsg.NodeID
				if len(initMsg.Nodes) > 0 {
					nodeIDs := append([]string{nodeID}, initMsg.Nodes...)
					// Sort to ensure consistent ordering
					for i := 0; i < len(nodeIDs); i++ {
						for j := i + 1; j < len(nodeIDs); j++ {
							if nodeIDs[i] > nodeIDs[j] {
								nodeIDs[i], nodeIDs[j] = nodeIDs[j], nodeIDs[i]
							}
						}
					}
				}
			case "init_done":
				log.Printf("Init done: %v", nodeIDs)
			}
		}
	}

	// Initialize the sequentially consistent key-value store
	seqKV, err := maelstrom.NewSeqKV(node, "seq-kv")
	if err != nil {
		log.Fatalf("Failed to create SeqKV: %v", err)
	}

	// Start handling messages asynchronously with WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		node.Run()
	}()

	log.Printf("Node ID: %s, Other nodes: %d", nodeID, len(nodeIDs)-1)

	// Initialize the counter key
	seqKV.Write([]byte{0}, []byte("0"), time.Second)

	for {
		if msg := <-node.Messages(); !msg.Done() {
			// Handle different message types
			switch msg.Type {
			case "add":
				handleAdd(msg, node, seqKV, &wg, initMsg.Nodes)
			case "read":
				handleRead(msg, node, seqKV, &wg, initMsg.Nodes)
			}
		}
	}
}

func handleAdd(msg *maelstrom.Message, node *maelstrom.Node, seqKV *maelstrom.SeqKV, wg *sync.WaitGroup, nodes []string) {
	body := msg.Body()
	addReq := new(addRequest)
	if err := json.Unmarshal(body, addReq); err != nil {
		log.Printf("Error parsing add request: %v", err)
		return
	}

	var ackCount int64 = 0
	var replyMsg *maelstrom.Message

	// Read current value from seq-kv
	currentValue, _ := seqKV.Read([]byte{}, []byte{0}, time.Second)
	initial := currentValue

	log.Printf("Add %d: current=%d, delta=%d", addReq.MsgID, initial, addReq.Delta)

	// For grow-only counter, we need to track acks per node
	// Each node tracks how many adds it has acknowledged
	// If an add is sent but doesn't get an ack from this node (network partition),
	// it still contributes if acknowledged by other nodes

	// Get the local counter value
	counterKey := []byte{0}
	counterValue, _ := seqKV.ReadInt(counterKey)

	// Check for concurrent modifications - use compare and swap to ensure atomicity
	newValue := counterValue + addReq.Delta
	ack := true // Assume ack initially

	// Try to get an ack from another node if needed (for distributed consistency)
	if len(nodes) > 1 {
		ctx := maelstrom.NewContext(addReq.TTL)

		// We'll use a simple approach: each node independently increments
		// and tracks its own acknowledged adds. After partition heals,
		// seq-kv's sequential consistency ensures all nodes see the same order.
	}

	// Write the new value to seq-kv
	if err := seqKV.Write(counterKey, []byte(fmt.Sprintf("%d", newValue)), time.Second); err != nil {
		log.Printf("Failed to write counter: %v", err)
		return
	}

	log.Printf("Add %d: ack=%d", addReq.MsgID, ackCount)

	// Send reply if we got a response (or send immediately for local ack)
	replyMsg = node.Reply()
	if err := json.Marshal(addOKResponse{
		MsgID:     addReq.MsgID,
		InReplyTo: 0, // We acknowledge ourselves
	}); err != nil {
		log.Printf("Failed to encode reply: %v", err)
	}

	node.Send(replyMsg)
}

func handleRead(msg *maelstrom.Message, node *maelstrom.Node, seqKV *maelstrom.SeqKV, wg *sync.WaitGroup, nodes []string) {
	body := msg.Body()
	readReq := new(readRequest)
	if err := json.Unmarshal(body, readReq); err != nil {
		log.Printf("Error parsing read request: %v", err)
		return
	}

	ctx := maelstrom.NewContext(time.Second)
	counterKey := []byte{0}

	value, _, _ := seqKV.ReadInt(counterKey, ctx)

	log.Printf("Read %d: value=%d", readReq.MsgID, value)

	replyMsg := node.Reply()
	if err := json.Marshal(readOKResponse{
		MsgID:     readReq.MsgID,
		InReplyTo: 0,
		Value:      value,
	}); err != nil {
		log.Printf("Failed to encode reply: %v", err)
	}

	node.Send(replyMsg)
}

