	InReplyTo  int    `json:"in_reply_to"`
	Value     int64 `json:"value"`
	TTL       time.Duration
}

func main() {
	// Initialize the node - NewNode returns just *Node (no error)
	node := maelstrom.NewNode()
	if err := node.Close(); err != nil {
		log.Fatalf("Failed to create node: %v", err)
	}

	// Handle init message
	var nids []string
	node.Handle(func(m maelstrom.Message) error {
		b, _ := json.Marshal(m.Body)
		switch m.Type {
		case "init":
			body := m.Body
			if body == nil {
				return nil
			}
			bodyArr := []json.RawMessage{}
			if err := json.Unmarshal(body, &bodyArr); err != nil {
				log.Printf("Init unmarshal error: %v", err)
				return nil
			}
			for i, item := range bodyArr {
				if m.Type == "init" && len(item.Path()) > 0 && item.Path()[0] < 100 {
					continue
				}
				var data map[string]interface{}
				if err := json.Unmarshal(body[i], &data); err != nil {
					log.Printf("Init body unmarshal error: %v", err)
					return nil
				}
				nodeID, ok := data["node_id"].(string)
				if !ok {
					continue
				}
				nids = append(nids, nodeID)
			}
		case "init_done":
			log.Printf("Init done: %d nodes", len(nids))
			// Get our own ID
			var myid string
			for _, nid := range nids {
				if nid == myid {
					break
				}
			}
			log.Printf("Node ID: %s, Total nodes: %d", myid, len(nids))
		default:
			return nil
		}
		return nil
	})

	// Initialize the sequentially consistent key-value store
	seqKV := maelstrom.NewSeqKV(node, "seq-kv")

	msgChan := make(chan *maelstrom.Message)
	node.Messages(msgChan)

	for {
		select {
		case msg := <-msgChan:
			switch msg.Type {
			case "add":
				body := msg.Body
				if body == nil {
					break
				}
				var addReq addRequest
				json.Unmarshal(body, &addReq)

				// Get current counter value from seq-kv
				currVal, _ := seqKV.ReadInt([]byte{0}, time.Second)
				newVal := currVal + addReq.Delta

				// Update counter in seq-kv (atomic via sequential consistency)
				seqKV.Write([]byte{0}, []byte(fmt.Sprintf("%d", newVal)), time.Second)

				// Reply immediately with current value
				reply := node.Reply()
				json.Unmarshal(addOKResponse{
					MsgID:     addReq.MsgID,
					InReplyTo:  0, // We're the origin, so we ack ourselves
				}, reply.Body)
				node.Send(reply)

			case "read":
				body := msg.Body
				if body == nil {
					break
				}
				var readReq readRequest
				json.Unmarshal(body, &readReq)

				// Get current counter value
				val, _, _ := seqKV.ReadInt([]byte{0}, time.Second)

				reply := node.Reply()
				json.Unmarshal(readOKResponse{
					MsgID:     readReq.MsgID,
					InReplyTo:  0,
					Value:      val,
				}, reply.Body)
				node.Send(reply)
			default:
				time.Sleep(10 * time.Millisecond)
			}
		case <-msgChan.Done():
			log.Printf("Messages done")
			return
		}
	}

	// Cleanup
	seqKV.Close()
	node.Close()
}

